command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "433e26a5278af97be4c58edc362549d52abf778a") { throw "main moved" }

git -C $env:GITHUB_WORKSPACE push origin --delete work/filter-presets
if ($LASTEXITCODE -ne 0) { throw "filter preset branch cleanup failed" }

Write-Host "FILTER_PRESET_WORK_BRANCH_DELETED"
